    hotdogs = image_patch.find("hotdog")
    fish_crackers = image_patch.find("fish crackers")

    if not hotdogs or not fish_crackers:
        return image_patch

    hotdog_centers = [(p.left + p.right) / 2 for p in hotdogs]
    fish_cracker_centers = [(p.left + p.right) / 2 for p in fish_crackers]

    for hotdog_center in hotdog_centers:
        for fish_cracker_center in fish_cracker_centers:
            if abs(hotdog_center - fish_cracker_center) < min(hotdogs[0].width, fish_crackers[0].width):
                return image_patch

    return hotdogs[0]

